#!/usr/bin/env node
// Generated by OrchestKit Claude Plugin
// Created: 2026-11-17
//
// Opens a Claude Design export safely and prints what is inside as JSON.
//
// Accepted inputs, recognised by content and never by file extension:
//   - a .zip          ("Download as .zip" in the design's Export menu)
//   - a single .html  ("Export as standalone HTML")
//   - a folder        (an export that was already unpacked)
//   - a .tar.gz       (the handoff bundle of the standalone claude.ai/design
//                      site; that site closes on 2026-12-14, remove this
//                      branch after that date)
//
// The archive layout is not documented by Anthropic, so nothing here assumes
// one: the script reports what it finds and the caller decides.
//
// Archives are untrusted input. Both readers below are written in plain Node
// so every byte lands only under the output folder: entry names that are
// absolute, contain "..", a backslash or a drive letter are refused, links are
// refused, and size and count are capped before and during extraction.
//
// Usage:
//   node inspect-export.mjs <export> [--out <dir>] [--open <file.html>]
//
// Exit codes: 0 readable (complete or incomplete), 1 refused or not a design
// export, 2 usage or IO error.

import { createHash } from 'node:crypto';
import {
  existsSync, lstatSync, mkdirSync, mkdtempSync, readFileSync, readdirSync, writeFileSync,
} from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { gunzipSync, inflateRawSync } from 'node:zlib';

const MAX_ENTRIES = 2000;
const MAX_TOTAL_BYTES = 200 * 1024 * 1024;
const MAX_INPUT_BYTES = 200 * 1024 * 1024;

class Refused extends Error {}

function fail(code, message) {
  console.error(message);
  process.exit(code);
}

// ─── arguments ──────────────────────────────────────────────────────────
const args = process.argv.slice(2);
let input = null;
let outDir = null;
let openHint = null;
for (let i = 0; i < args.length; i += 1) {
  if (args[i] === '--out') outDir = args[++i];
  else if (args[i] === '--open') openHint = args[++i];
  else if (!input) input = args[i];
  else fail(2, `Unexpected argument: ${args[i]}`);
}
if (!input) fail(2, 'Usage: node inspect-export.mjs <export> [--out <dir>] [--open <file.html>]');
if (!existsSync(input)) fail(2, `Not found: ${input}`);

// ─── entry name safety (shared by both archive readers) ─────────────────
function safeName(raw) {
  if (!raw || raw.includes('\0') || raw.includes('\\')) throw new Refused(`unsafe entry name: ${JSON.stringify(raw)}`);
  if (raw.startsWith('/') || raw.startsWith('~') || /^[A-Za-z]:/.test(raw)) {
    throw new Refused(`absolute entry name: ${raw}`);
  }
  const parts = raw.split('/').filter((p) => p !== '' && p !== '.');
  if (parts.includes('..')) throw new Refused(`entry name leaves the archive: ${raw}`);
  return parts.join('/');
}

// Two entries with one name, or a name that is both a file and a folder of
// another entry, would overwrite or fail half way through: refuse them up front.
function refuseNameClashes(names) {
  const seen = new Set();
  for (const name of names) {
    if (seen.has(name)) throw new Refused(`two entries share the name: ${name}`);
    seen.add(name);
  }
  for (const name of names) {
    const parts = name.split('/');
    for (let i = 1; i < parts.length; i += 1) {
      const parent = parts.slice(0, i).join('/');
      if (seen.has(parent)) throw new Refused(`an entry is both a file and a folder: ${parent}`);
    }
  }
}

function writeInside(root, rel, data) {
  const target = path.resolve(root, rel);
  if (target !== root && !target.startsWith(root + path.sep)) throw new Refused(`entry escapes the output folder: ${rel}`);
  mkdirSync(path.dirname(target), { recursive: true });
  writeFileSync(target, data);
}

// ─── zip reader ─────────────────────────────────────────────────────────
function extractZip(buf, root) {
  const EOCD = 0x06054b50;
  let eocd = -1;
  for (let i = buf.length - 22; i >= Math.max(0, buf.length - 65557); i -= 1) {
    if (buf.readUInt32LE(i) === EOCD) { eocd = i; break; }
  }
  if (eocd < 0) throw new Refused('not a readable zip (no end record)');
  const count = buf.readUInt16LE(eocd + 10);
  const cdOffset = buf.readUInt32LE(eocd + 16);
  if (count === 0xffff || cdOffset === 0xffffffff) throw new Refused('zip64 archives are not supported');
  if (count > MAX_ENTRIES) throw new Refused(`too many entries (${count} > ${MAX_ENTRIES})`);

  const entries = [];
  let declared = 0;
  let p = cdOffset;
  for (let n = 0; n < count; n += 1) {
    if (p + 46 > buf.length || buf.readUInt32LE(p) !== 0x02014b50) throw new Refused('corrupt zip directory');
    const madeBy = buf.readUInt16LE(p + 4);
    const flags = buf.readUInt16LE(p + 8);
    const method = buf.readUInt16LE(p + 10);
    const compSize = buf.readUInt32LE(p + 20);
    const size = buf.readUInt32LE(p + 24);
    const nameLen = buf.readUInt16LE(p + 28);
    const extraLen = buf.readUInt16LE(p + 30);
    const commentLen = buf.readUInt16LE(p + 32);
    const attrs = buf.readUInt32LE(p + 38);
    const localOffset = buf.readUInt32LE(p + 42);
    const rawName = buf.toString('utf8', p + 46, p + 46 + nameLen);
    p += 46 + nameLen + extraLen + commentLen;

    if (flags & 1) throw new Refused('encrypted zip entries are not supported');
    if ((madeBy >> 8) === 3 && ((attrs >>> 16) & 0o170000) === 0o120000) {
      throw new Refused(`links are not allowed in an export: ${rawName}`);
    }
    const name = safeName(rawName);
    if (rawName.endsWith('/') || name === '') continue;
    if (method !== 0 && method !== 8) throw new Refused(`unsupported compression in ${rawName}`);
    declared += size;
    if (declared > MAX_TOTAL_BYTES) throw new Refused('export is larger than the 200 MB limit');
    entries.push({ name, method, compSize, size, localOffset });
  }

  refuseNameClashes(entries.map((e) => e.name));

  // Decode everything in memory first: the declared sizes are already capped
  // above, and every entry must match its own declared size, so a refused
  // archive leaves nothing on disk and cannot write more than the cap.
  const decoded = [];
  for (const e of entries) {
    const h = e.localOffset;
    if (h + 30 > buf.length || buf.readUInt32LE(h) !== 0x04034b50) throw new Refused(`corrupt zip entry: ${e.name}`);
    const start = h + 30 + buf.readUInt16LE(h + 26) + buf.readUInt16LE(h + 28);
    if (start + e.compSize > buf.length) throw new Refused(`zip entry runs past the end of the file: ${e.name}`);
    const raw = buf.subarray(start, start + e.compSize);
    let data;
    if (e.method === 0) {
      // A stored entry is written as is, so its two size fields must agree.
      if (e.compSize !== e.size) throw new Refused(`entry does not match its declared size: ${e.name}`);
      data = raw;
    } else {
      try {
        // maxOutputLength makes a lying size field fail instead of filling the disk
        data = inflateRawSync(raw, { maxOutputLength: Math.max(e.size, 1) });
      } catch {
        throw new Refused(`entry does not match its declared size: ${e.name}`);
      }
    }
    decoded.push({ name: e.name, data });
  }
  for (const d of decoded) writeInside(root, d.name, d.data);
}

// ─── tar.gz reader (standalone-site handoff bundle, until 2026-12-14) ───
function extractTarGz(buf, root) {
  let tar;
  try {
    tar = gunzipSync(buf, { maxOutputLength: MAX_TOTAL_BYTES });
  } catch {
    throw new Refused('not a readable .tar.gz, or larger than the 200 MB limit');
  }
  const text = (from, len) => tar.toString('utf8', from, from + len).replace(/\0.*$/s, '');
  let p = 0;
  let nextName = null;
  const entries = [];
  while (p + 512 <= tar.length) {
    const header = tar.subarray(p, p + 512);
    if (header.every((b) => b === 0)) break;
    const size = parseInt(text(p + 124, 12).trim() || '0', 8);
    const type = String.fromCharCode(header[156] || 48);
    const prefix = text(p + 345, 155);
    const rawName = nextName ?? (prefix ? `${prefix}/${text(p, 100)}` : text(p, 100));
    const dataStart = p + 512;
    // A negative or unreadable size would move the cursor backwards and loop forever.
    if (!Number.isInteger(size) || size < 0 || dataStart + size > tar.length) throw new Refused('corrupt tar entry');
    p = dataStart + Math.ceil(size / 512) * 512;

    if (type === 'x' || type === 'L') {
      // pax header or GNU long name: carries the real name of the next entry
      const body = tar.toString('utf8', dataStart, dataStart + size);
      if (type === 'L') nextName = body.replace(/\0.*$/s, '');
      else {
        const m = /^\d+ path=(.*)$/m.exec(body);
        if (m) nextName = m[1];
      }
      continue;
    }
    nextName = null;
    if (type === 'g') continue;
    if (type === '1' || type === '2') throw new Refused(`links are not allowed in an export: ${rawName}`);
    const name = safeName(rawName);
    if (type === '5' || name === '') continue;
    if (type !== '0') throw new Refused(`unsupported tar entry type "${type}": ${rawName}`);
    entries.push({ name, data: tar.subarray(dataStart, dataStart + size) });
    if (entries.length > MAX_ENTRIES) throw new Refused(`too many entries (> ${MAX_ENTRIES})`);
  }
  refuseNameClashes(entries.map((e) => e.name));
  // Write only after every name and type passed, so a refused archive leaves nothing behind.
  for (const e of entries) writeInside(root, e.name, e.data);
}

// ─── inventory ──────────────────────────────────────────────────────────
function walk(root) {
  const files = [];
  const warnings = [];
  let total = 0;
  const visit = (dir) => {
    for (const name of readdirSync(dir).sort()) {
      const abs = path.join(dir, name);
      const st = lstatSync(abs);
      const rel = path.relative(root, abs).split(path.sep).join('/');
      if (st.isSymbolicLink()) { warnings.push(`skipped link: ${rel}`); continue; }
      if (st.isDirectory()) {
        if (name === 'node_modules' || name === '.git') { warnings.push(`skipped folder: ${rel}`); continue; }
        visit(abs);
      } else if (st.isFile()) {
        total += st.size;
        files.push({ rel, size: st.size });
        if (files.length > MAX_ENTRIES) throw new Refused(`too many files (> ${MAX_ENTRIES})`);
        if (total > MAX_TOTAL_BYTES) throw new Refused('export is larger than the 200 MB limit');
      }
    }
  };
  visit(root);
  return { files, warnings };
}

function inventory(root, kind, exportId) {
  // An archive usually wraps everything in one top-level folder: step into it.
  for (let i = 0; i < 2; i += 1) {
    const top = readdirSync(root).filter((n) => !n.startsWith('.') && n !== '__MACOSX');
    if (top.length === 1 && lstatSync(path.join(root, top[0])).isDirectory()) root = path.join(root, top[0]);
    else break;
  }
  const { files, warnings } = walk(root);
  const ext = (f) => path.extname(f.rel).toLowerCase();
  const rels = (list) => list.map((f) => f.rel);
  const html = rels(files.filter((f) => ['.html', '.htm'].includes(ext(f))));
  const readme = rels(files.filter((f) => /^readme(\.(md|txt))?$/i.test(f.rel)))[0] ?? null;
  const chats = rels(files.filter((f) => /^chats\/[^/]+\.md$/i.test(f.rel)));
  const tokenFiles = rels(files.filter((f) => /(^|[/._-])tokens?([._-][^/]*)?\.(json|css)$/i.test(f.rel)
    || /design-tokens[^/]*\.(json|css)$/i.test(f.rel)));
  const assetExt = ['.png', '.jpg', '.jpeg', '.svg', '.webp', '.gif', '.avif', '.woff', '.woff2', '.ttf', '.otf'];
  const codeExt = ['.js', '.mjs', '.jsx', '.ts', '.tsx'];

  // The standalone-site bundle put prototypes under project/ and its chat
  // transcripts under chats/. Remove this special case after 2026-12-14.
  const legacy = kind === 'tar.gz' || (readme !== null && chats.length > 0);
  const candidates = legacy && html.some((h) => h.startsWith('project/'))
    ? html.filter((h) => h.startsWith('project/')) : html;

  let primary = null;
  if (candidates.length > 0) {
    const hinted = openHint && candidates.find((h) => h === openHint || path.basename(h) === path.basename(openHint));
    primary = hinted || candidates.find((h) => h === 'index.html') || candidates[0];
    if (openHint && !hinted) warnings.push(`--open ${openHint} is not in the export; using ${primary}`);
    if (!hinted && candidates.length > 1 && primary !== 'index.html') {
      warnings.push(`several HTML files and no index.html; picked ${primary} (first by name). Pass --open to choose.`);
    }
  }

  return {
    kind,
    layout: legacy ? 'standalone-handoff' : 'export',
    bundle_id: exportId,
    root,
    status: html.length > 0 ? 'complete' : 'incomplete',
    primary_html: primary,
    html,
    css: rels(files.filter((f) => ext(f) === '.css')),
    token_files: tokenFiles,
    readme,
    chats,
    code_files: files.filter((f) => codeExt.includes(ext(f))).length,
    asset_files: files.filter((f) => assetExt.includes(ext(f))).length,
    file_count: files.length,
    warnings,
  };
}

// ─── main ───────────────────────────────────────────────────────────────
try {
  const st = lstatSync(input);
  if (st.isSymbolicLink()) throw new Refused('the export path is a link; pass the real file or folder');
  let result;
  if (st.isDirectory()) {
    const root = path.resolve(input);
    const { files } = walk(root);
    const hash = createHash('sha256');
    for (const f of files) hash.update(`${f.rel}\0${f.size}\0`).update(readFileSync(path.join(root, f.rel)));
    result = inventory(root, 'folder', hash.digest('hex'));
  } else {
    if (!st.isFile() || st.size === 0) fail(2, `Not a regular non-empty file: ${input}`);
    if (st.size > MAX_INPUT_BYTES) throw new Refused('export is larger than the 200 MB limit');
    const buf = readFileSync(input);
    const id = createHash('sha256').update(buf).digest('hex');
    const root = path.resolve(outDir ?? mkdtempSync(path.join(tmpdir(), 'design-export-')));
    mkdirSync(root, { recursive: true });
    if (readdirSync(root).length > 0) fail(2, `Output folder is not empty: ${root}`);

    const head = buf.subarray(0, 4096).toString('utf8').toLowerCase();
    if (buf.length >= 4 && buf.readUInt32LE(0) === 0x04034b50) {
      extractZip(buf, root);
      result = inventory(root, 'zip', id);
    } else if (buf[0] === 0x1f && buf[1] === 0x8b) {
      extractTarGz(buf, root);
      result = inventory(root, 'tar.gz', id);
    } else if (head.includes('<!doctype html') || head.includes('<html')) {
      writeInside(root, path.basename(input).replace(/[^\w.-]/g, '_'), buf);
      result = inventory(root, 'html', id);
    } else {
      throw new Refused('not a design export: expected a .zip, a standalone .html, a folder, or a .tar.gz handoff bundle');
    }
  }
  // No process.exit here: exiting right after a write truncates a large
  // inventory when stdout is a pipe. Let the process end on its own.
  process.stdout.write(`${JSON.stringify(result, null, 2)}\n`);
  process.exitCode = 0;
} catch (err) {
  if (err instanceof Refused) fail(1, `Refused: ${err.message}`);
  fail(2, `Error: ${err.message}`);
}
